{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.B2B_RECONCILIATION_SUMMARY AS WITH dates AS ( SELECT DATE \'2026-08-01\' AS uc_start_date, CONVERT_TIMEZONE( \'Asia/Kolkata\', CURRENT_TIMESTAMP() )::DATE AS end_date ), uc_raw AS ( SELECT uc.order_name, uc.invoice_code, uc.awb, uc.dispatched_timestamp, uc.marketplace_mapped, uc.sku, uc.selling_price, uc.warehouse_name, UPPER(TRIM(uc.sku::STRING)) AS sku_key, CASE WHEN uc.marketplace_mapped IN ( \'M-NOW\', \'M_NOW_WESTBENGAL\' ) THEN \'MYNTRA_NOW\' ELSE uc.marketplace_mapped END AS marketplace_group, COALESCE( NULLIF(TRIM(uc.order_name::STRING), \'\'), NULLIF(TRIM(uc.invoice_code::STRING), \'\'), NULLIF(TRIM(uc.awb::STRING), \'\'), \'NO_BATCH_REFERENCE\' ) AS batch_reference FROM SNITCH_DB.MAPLEMONK.UNICOMMERCE_FACT_ITEMS_INTERMEDIATE_2024 uc CROSS JOIN dates WHERE uc.marketplace_mapped IN ( \'FLIPKART_SOR\', \'MYNTRA_SJIT\', \'M-NOW\', \'SLIKK\', \'M_NOW_WESTBENGAL\', \'KNOT\', \'ZILO\', \'INSTAMART\', \'NOON\' ) AND uc.dispatched_timestamp IS NOT NULL AND uc.dispatched_timestamp::DATE BETWEEN dates.uc_start_date AND dates.end_date AND NULLIF( TRIM(uc.sku::STRING), \'\' ) IS NOT NULL AND UPPER(TRIM(uc.sku::STRING)) <> \'DUMMY-BOX-01\' AND COALESCE( uc.warehouse_name, \'\' ) NOT ILIKE \'%surat-VRMall%\' ), uc_prepared AS ( SELECT uc.*, marketplace_group || \'|\' || COALESCE(warehouse_name, \'\') || \'|\' || TO_VARCHAR(dispatched_timestamp::DATE) || \'|\' || batch_reference AS uc_batch_key FROM uc_raw uc ), uc_sku AS ( SELECT uc_batch_key, marketplace_group, MIN(dispatched_timestamp::DATE) AS dispatch_date, sku_key, COUNT(*)::NUMBER(38,0) AS uc_quantity, ROUND( COALESCE( SUM(selling_price), 0 ), 2 ) AS uc_value FROM uc_prepared GROUP BY uc_batch_key, marketplace_group, sku_key ), uc_batch AS ( SELECT uc_batch_key, marketplace_group, MIN(dispatch_date) AS dispatch_date, SUM(uc_quantity)::NUMBER(38,0) AS uc_total_quantity, COUNT(*)::NUMBER(38,0) AS uc_distinct_sku_count, ROUND( SUM(uc_value), 2 ) AS uc_total_value, MD5( LISTAGG( sku_key || \':\' || TO_VARCHAR(uc_quantity), \'|\' ) WITHIN GROUP ( ORDER BY sku_key ) ) AS uc_signature FROM uc_sku GROUP BY uc_batch_key, marketplace_group ), logic_raw AS ( SELECT DISTINCT raw._airbyte_data FROM SNITCH_DB.MAPLEMONK._AIRBYTE_RAW_LOGICERPNEW_GET_SALE_INVOICE raw CROSS JOIN dates WHERE TRIM( raw._airbyte_data:\"Branch_Code\"::STRING ) IN (\'2\',\'8\',\'94\') AND TRY_TO_DATE( raw._airbyte_data:\"Bill_Date\"::STRING, \'DD/MM/YYYY\' ) BETWEEN dates.uc_start_date AND dates.end_date ), logic_item_rows AS ( SELECT TRIM( raw._airbyte_data:\"Branch_Code\"::STRING ) AS branch_code, TRY_TO_DATE( raw._airbyte_data:\"Bill_Date\"::STRING, \'DD/MM/YYYY\' ) AS bill_date, COALESCE( NULLIF( TRIM( raw._airbyte_data:\"New_Bill_No\"::STRING ), \'\' ), NULLIF( TRIM( raw._airbyte_data:\"Order_No\"::STRING ), \'\' ), NULLIF( TRIM( raw._airbyte_data:\"Gr_Number\"::STRING ), \'\' ), MD5( TO_JSON(raw._airbyte_data) ) ) AS logic_invoice_reference, UPPER( COALESCE( raw._airbyte_data:\"Customer_Name\"::STRING, \'\' ) || \' | \' || COALESCE( raw._airbyte_data:\"Account_Name\"::STRING, \'\' ) ) AS party_text, UPPER( TRIM( item.value:\"AddlItemCode\"::STRING ) ) AS sku_key, COALESCE( TRY_TO_NUMBER( item.value:\"Quantity\"::STRING ), 0 )::NUMBER(38,0) AS logic_quantity FROM logic_raw raw, LATERAL FLATTEN( INPUT => TRY_PARSE_JSON( raw._airbyte_data:\"LstItems\"::STRING ) ) item WHERE NULLIF( TRIM( item.value:\"AddlItemCode\"::STRING ), \'\' ) IS NOT NULL ), logic_classified AS ( SELECT branch_code, bill_date, logic_invoice_reference, sku_key, logic_quantity, CASE WHEN party_text ILIKE \'%FLIPKART INDIA PRIVATE LIMITED%\' THEN \'FLIPKART_SOR\' WHEN party_text ILIKE \'%SJIT%\' THEN \'MYNTRA_SJIT\' WHEN party_text ILIKE \'%MYNTRA JABONG%\' OR party_text ILIKE \'%M-NOW%\' OR party_text ILIKE \'%MNOW%\' THEN \'MYNTRA_NOW\' WHEN party_text ILIKE \'%BANDIDOS RETAIL LLC%\' THEN \'NOON\' WHEN party_text ILIKE \'%SPRINTPRO%\' OR party_text ILIKE \'%SLIKK%\' THEN \'SLIKK\' WHEN party_text ILIKE \'%INSTAMART%\' OR party_text ILIKE \'%CLOUDKART%\' OR party_text ILIKE \'%CLOUDSTORE%\' OR party_text ILIKE \'%JUPITER KART%\' OR party_text ILIKE \'%MOKSH ENTERPRISES%\' THEN \'INSTAMART\' WHEN party_text ILIKE \'%KNOT%\' THEN \'KNOT\' WHEN party_text ILIKE \'%ZILO%\' THEN \'ZILO\' ELSE NULL END AS marketplace_group FROM logic_item_rows ), logic_sku AS ( SELECT marketplace_group, marketplace_group || \'|\' || branch_code || \'|\' || TO_VARCHAR(bill_date) || \'|\' || logic_invoice_reference AS logic_batch_key, MIN(bill_date) AS bill_date, sku_key, SUM(logic_quantity)::NUMBER(38,0) AS logic_quantity FROM logic_classified WHERE marketplace_group IS NOT NULL GROUP BY marketplace_group, branch_code, bill_date, logic_invoice_reference, sku_key ), logic_batch AS ( SELECT marketplace_group, logic_batch_key, MIN(bill_date) AS bill_date, SUM(logic_quantity)::NUMBER(38,0) AS logic_total_quantity, COUNT(*)::NUMBER(38,0) AS logic_distinct_sku_count, MD5( LISTAGG( sku_key || \':\' || TO_VARCHAR(logic_quantity), \'|\' ) WITHIN GROUP ( ORDER BY sku_key ) ) AS logic_signature FROM logic_sku GROUP BY marketplace_group, logic_batch_key ), uc_exact_ranked AS ( SELECT uc.*, ROW_NUMBER() OVER ( PARTITION BY marketplace_group, uc_signature ORDER BY uc_batch_key ) AS signature_sequence FROM uc_batch uc ), logic_exact_ranked AS ( SELECT logic.*, ROW_NUMBER() OVER ( PARTITION BY marketplace_group, logic_signature ORDER BY bill_date, logic_batch_key ) AS signature_sequence FROM logic_batch logic ), exact_matches AS ( SELECT uc.uc_batch_key, logic.logic_batch_key, uc.uc_total_quantity AS matched_quantity FROM uc_exact_ranked uc JOIN logic_exact_ranked logic ON uc.marketplace_group = logic.marketplace_group AND uc.uc_signature = logic.logic_signature AND uc.signature_sequence = logic.signature_sequence ), remaining_uc AS ( SELECT uc.* FROM uc_batch uc LEFT JOIN exact_matches exact ON uc.uc_batch_key = exact.uc_batch_key WHERE exact.uc_batch_key IS NULL ), remaining_logic AS ( SELECT logic.* FROM logic_batch logic LEFT JOIN exact_matches exact ON logic.logic_batch_key = exact.logic_batch_key WHERE exact.logic_batch_key IS NULL ), partial_candidates AS ( SELECT uc.uc_batch_key, logic.logic_batch_key, uc.uc_total_quantity, uc.uc_distinct_sku_count, logic.logic_total_quantity, COUNT_IF( COALESCE( logic_item.logic_quantity, 0 ) > 0 ) AS overlapping_sku_count, SUM( LEAST( uc_item.uc_quantity, COALESCE( logic_item.logic_quantity, 0 ) ) )::NUMBER(38,0) AS matched_quantity FROM remaining_uc uc JOIN uc_sku uc_item ON uc.uc_batch_key = uc_item.uc_batch_key JOIN remaining_logic logic ON uc.marketplace_group = logic.marketplace_group LEFT JOIN logic_sku logic_item ON logic.logic_batch_key = logic_item.logic_batch_key AND uc_item.sku_key = logic_item.sku_key GROUP BY uc.uc_batch_key, logic.logic_batch_key, uc.uc_total_quantity, uc.uc_distinct_sku_count, logic.logic_total_quantity HAVING SUM( LEAST( uc_item.uc_quantity, COALESCE( logic_item.logic_quantity, 0 ) ) ) > 0 ), partial_ranked AS ( SELECT candidate.*, matched_quantity::FLOAT / NULLIF( uc_total_quantity, 0 ) AS quantity_coverage, overlapping_sku_count::FLOAT / NULLIF( uc_distinct_sku_count, 0 ) AS sku_coverage, ROW_NUMBER() OVER ( PARTITION BY uc_batch_key ORDER BY matched_quantity DESC, overlapping_sku_count DESC, ABS( uc_total_quantity - logic_total_quantity ) ASC, logic_batch_key ) AS rn FROM partial_candidates candidate ), partial_matches AS ( SELECT uc_batch_key, logic_batch_key, matched_quantity FROM partial_ranked WHERE rn = 1 AND ( quantity_coverage >= 0.50 OR sku_coverage >= 0.50 ) ), batch_result AS ( SELECT uc.dispatch_date, uc.marketplace_group, uc.uc_batch_key, uc.uc_total_quantity, uc.uc_total_value, CASE WHEN exact.uc_batch_key IS NOT NULL THEN uc.uc_total_quantity WHEN partial.uc_batch_key IS NOT NULL THEN LEAST( partial.matched_quantity, uc.uc_total_quantity ) ELSE 0 END::NUMBER(38,0) AS present_in_logic_quantity FROM uc_batch uc LEFT JOIN exact_matches exact ON uc.uc_batch_key = exact.uc_batch_key LEFT JOIN partial_matches partial ON uc.uc_batch_key = partial.uc_batch_key ), marketplace_summary AS ( SELECT dispatch_date, marketplace_group, SUM(uc_total_quantity) AS present_in_uc, SUM(present_in_logic_quantity) AS present_in_logic, SUM( GREATEST( uc_total_quantity - present_in_logic_quantity, 0 ) ) AS missing_in_logic, ROUND( SUM(uc_total_value), 2 ) AS uc_value, ROUND( SUM( uc_total_value * ( present_in_logic_quantity::FLOAT / NULLIF( uc_total_quantity, 0 ) ) ), 2 ) AS present_in_logic_value, ROUND( SUM( uc_total_value * ( GREATEST( uc_total_quantity - present_in_logic_quantity, 0 )::FLOAT / NULLIF( uc_total_quantity, 0 ) ) ), 2 ) AS missing_in_logic_value FROM batch_result GROUP BY dispatch_date, marketplace_group ) SELECT dispatch_date, marketplace_group, present_in_uc, present_in_logic, missing_in_logic, uc_value, present_in_logic_value, missing_in_logic_value FROM marketplace_summary UNION ALL SELECT dispatch_date, \'TOTAL\', SUM(present_in_uc), SUM(present_in_logic), SUM(missing_in_logic), ROUND(SUM(uc_value), 2), ROUND(SUM(present_in_logic_value), 2), ROUND(SUM(missing_in_logic_value), 2) FROM marketplace_summary GROUP BY dispatch_date ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            